// Point Wrangle: build an orient quaternion that rotates a
// reference up-vector onto each point's surface normal. Copy to
// Points reads p@orient automatically.
vector up = chv("up");            // e.g. {0, 1, 0}
vector n  = normalize(@N);
p@orient  = dihedral(up, n);

// Point Wrangle: smaller pscale where neighbours are dense.
int h = pcopen(0, "P", @P, chf("radius"), chi("maxpts"));
int n = pcnumfound(h);
@pscale = fit(n, 1, chi("maxpts"), chf("maxsize"), chf("minsize"));
pcclose(h);

// Point/Prim Wrangle downstream of a Connectivity SOP that
// writes i@class. Each piece gets a stable random colour.
@Cd = rand(i@class * 0.731 + 12.3);

// Detail Wrangle: connect every input point, in order, into one
// open polyline.
int n    = npoints(0);
int prim = addprim(0, "polyline");
for (int i = 0; i < n; i++)
    addvertex(0, prim, i);

// Point Wrangle: accumulate octaves of absolute noise (ridged
// fBm) and push each point along its normal.
float amp  = chf("amp");
float freq = chf("freq");
float n = 0;
for (int o = 0; o < 4; o++) {
    float g = pow(2.0, o);
    n += abs(noise(@P * freq * g)) / g;
}
@P += normalize(@N) * n * amp;

// Point Wrangle: remove any point outside a spherical radius.
if (length(@P) > chf("radius"))
    removepoint(0, @ptnum);

// Point Wrangle (after a Normal SOP): higher @curve where the
// surface bends away from its neighbours.
int nb[] = neighbours(0, @ptnum);
vector navg = {0, 0, 0};
foreach (int pt; nb)
    navg += point(0, "N", pt);
navg = normalize(navg / max(len(nb), 1));
f@curve = 1.0 - dot(navg, normalize(@N));

// Primitive Wrangle: write point attribute curveu in [0,1] by
// accumulated arc length along each polyline.
int pts[] = primpoints(0, @primnum);
float total = 0;
for (int i = 1; i < len(pts); i++)
    total += distance(point(0, "P", pts[i-1]), point(0, "P", pts[i]));
float run = 0;
setpointattrib(0, "curveu", pts[0], 0.0);
for (int i = 1; i < len(pts); i++) {
    run += distance(point(0, "P", pts[i-1]), point(0, "P", pts[i]));
    setpointattrib(0, "curveu", pts[i], total > 0 ? run / total : 0.0);
}

// Point Wrangle: independent random orient, size and colour per
// copy. Offsetting the seed decorrelates each attribute.
float seed = @ptnum;
p@orient = quaternion(rand(seed) * 2 * PI, {0, 1, 0});
@pscale  = fit01(rand(seed + 1.7), chf("smin"), chf("smax"));
@Cd      = set(rand(seed + 3.1), rand(seed + 5.2), rand(seed + 7.3));

// Point Wrangle: snap each position to the nearest grid cell so a
// following Fuse SOP welds coincident points cleanly.
float g = chf("grid");
@P = round(@P / g) * g;
